from __future__ import annotations

from typing import List

from .problem import Problem


def render_problems_md(problems: List[Problem]) -> str:
    lines = [
        "# Problem catalogue",
        "",
        "_Generated by `leetforge docs` - do not edit by hand. IDs are LeetCode problem numbers._",
        "",
        "| # | Title | Difficulty | Tags | Pattern | Approaches (time / space) |",
        "|---|---|---|---|---|---|",
    ]
    for p in problems:
        apps = "<br>".join(f"`{a}`: {t} / {s}" for a, (t, s) in p.complexity.items())
        lines.append(f"| {p.id} | {p.title} | {p.difficulty} | {', '.join(p.tags)} | {p.pattern} | {apps} |")
    n_apps = sum(len(p.approaches) for p in problems)
    lines += ["", f"**{len(problems)} problems, {n_apps} implementations.**", ""]
    return "\n".join(lines)
